fn save_order(conn: &mut PgConnection, o: &Order, lines: &[NewOrderLine]) -> QueryResult<()> {
    conn.transaction(|conn| {
        diesel::delete(order_line::table.filter(order_line::order_id.eq(o.id)))
            .execute(conn)?;
        diesel::insert_into(order_line::table).values(lines).execute(conn)?;
        Ok(())
    })
}
